188: /** Render a destructible battle structure without leaking campaign art into the engine model. */
189: export function candidate01StructureMarkup(
190:   state: StructureState,
191:   def: StructureDef,
192:   ownerColor?: string,
193: ): string | null {
194:   const topic = CANDIDATE_01_STRUCTURE_ART[state.type];
195:   if (!topic) return null;
196:   const record = candidate01Asset(topic);
197:   const visualState = state.hp <= def.maxHp * 0.5 || state.disabled ? 'damaged' : ownerColor ? 'captured' : 'normal';
198:   const frame = structureFrame(record, visualState);
199:   const ratio = gaugeRatio(state.hp, def.maxHp);
200:   return `${structureAssetMarkup(record, frame, ownerColor)}${tileGaugeBar(ratio)}`;
201: }
